example_code:
committed = {"app.js": ['console.log("Hello");']}
working = {"app.js": ['console.log("Hello");', "const PORT = 3000;"]}

def status():
    modified = [f for f in working if working[f] != committed.get(f)]
    print("Changes not staged for commit:")
    for f in modified:
        print(f"  modified: {f}")

def diff():
    for f in working:
        old = committed.get(f, [])
        new = working[f]
        if old != new:
            print(f"--- a/{f}")
            print(f"+++ b/{f}")
            for line in old:
                print(f" {line}")
            for line in new[len(old):]:
                print(f"+{line}")

status()
diff()

